//! What hosts can list and look up: countries, cities, airports and what a place name is.

use std::sync::LazyLock;

use jiff::tz::TimeZone;

use super::{AIRPORTS, INDEX, Location, Place, PlaceKind, city_lines, locate};

/// Generated by scripts/countries.py.
const COUNTRIES: &str = include_str!("countries.txt");

/// A country or territory of ISO 3166.
#[derive(Clone, Debug, PartialEq)]
pub struct Country {
    /// "JP".
    pub code: &'static str,
    /// "Japan".
    pub name: &'static str,
    /// Its currency's code: "JPY". Antarctica has none.
    pub currency: Option<&'static str>,
    /// Its IANA zones, the principal one first.
    pub zones: Vec<&'static str>,
}

static ALL: LazyLock<Vec<Country>> = LazyLock::new(|| {
    let lines = COUNTRIES.lines().filter(|l| !l.starts_with('#'));
    lines
        .filter_map(|line| {
            let mut fields = line.split('\t');
            let (code, name, currency, zones) = (fields.next()?, fields.next()?, fields.next()?, fields.next()?);
            let zones = zones.split(',').filter(|z| !z.is_empty()).collect();
            Some(Country { code, name, currency: (!currency.is_empty()).then_some(currency), zones })
        })
        .collect()
});

/// Every country, by code.
pub fn countries() -> &'static [Country] {
    &ALL
}

/// A country by its code ("jp") or name ("Japan"), in any case.
pub fn country(name: &str) -> Option<&'static Country> {
    let name = name.trim();
    let country = ALL.iter().find(|c| c.code.eq_ignore_ascii_case(name) || c.name.eq_ignore_ascii_case(name));
    // Other names of a country lead to its zone: "USA", "Holland".
    country.or_else(|| {
        let listed = INDEX.get(&name.to_lowercase()).filter(|l| l.kind == PlaceKind::Country)?;
        country_of_zone(&listed.zone)
    })
}

/// The country a zone belongs to: "Asia/Tokyo" is Japan's.
pub fn country_of_zone(id: &str) -> Option<&'static Country> {
    ALL.iter().find(|c| c.zones.contains(&id))
}

/// A city of the bundled GeoNames list.
#[derive(Clone, Debug, PartialEq)]
pub struct City {
    /// Lowercase, as lines read it: "new york city".
    pub name: &'static str,
    /// Its IANA zone: "America/New_York".
    pub zone: &'static str,
    pub latitude: f64,
    pub longitude: f64,
}

/// Every city of the bundled list, by name.
pub fn all_cities() -> impl Iterator<Item = City> {
    city_lines().lines().filter_map(|line| {
        let mut fields = line.split('\t');
        let (name, zone) = (fields.next()?, fields.next()?);
        let latitude = fields.next()?.parse().ok()?;
        let longitude = fields.next()?.parse().ok()?;
        Some(City { name, zone, latitude, longitude })
    })
}

/// An airport by its IATA code.
#[derive(Clone, Debug, PartialEq)]
pub struct Airport {
    /// "JFK".
    pub code: String,
    pub zone: &'static str,
    pub latitude: f64,
    pub longitude: f64,
}

/// Every bundled airport, by code.
pub fn airports() -> impl Iterator<Item = Airport> {
    AIRPORTS.lines().filter(|l| !l.starts_with('#')).filter_map(|line| {
        let (code, rest) = line.split_once(" = ")?;
        let mut fields = rest.split_whitespace();
        let zone = fields.next()?;
        let latitude = fields.next()?.parse().ok()?;
        let longitude = fields.next()?.parse().ok()?;
        Some(Airport { code: code.to_uppercase(), zone, latitude, longitude })
    })
}

/// Airports within `km` of a place, nearest first, with their distance.
pub fn airports_near(location: &Location, km: f64) -> Vec<(Airport, f64)> {
    let mut near: Vec<_> = airports()
        .map(|a| {
            let at = Location { zone: location.zone.clone(), latitude: a.latitude, longitude: a.longitude };
            let distance = super::distance_km(location, &at);
            (a, distance)
        })
        .filter(|(_, d)| *d <= km)
        .collect();
    near.sort_by(|a, b| a.1.total_cmp(&b.1));
    near
}

/// What a place name is: its kind, zone, where it is and its country.
#[derive(Clone, Debug)]
pub struct PlaceInfo {
    /// As answers write it: "Tokyo", "PST".
    pub name: String,
    pub kind: PlaceKind,
    pub zone: TimeZone,
    /// For cities and airports; regions and zones have no single place.
    pub location: Option<Location>,
    pub country: Option<&'static Country>,
}

/// A built-in place by name, as lines write it: "Tokyo", "JFK", "Texas", "PST".
pub fn place(name: &str) -> Option<PlaceInfo> {
    let key = name.trim().replace('-', " ").to_lowercase();
    let zone = super::find(&key)?;
    let Place { name, kind, .. } = Place::written(name.trim(), zone.clone());
    let location = match kind {
        PlaceKind::City | PlaceKind::Airport => locate(&key),
        _ => None,
    };
    let country = match kind {
        PlaceKind::Country => country(&key).or_else(|| country_of_zone(zone.iana_name()?)),
        PlaceKind::TimeZone => None,
        _ => zone.iana_name().and_then(country_of_zone),
    };
    Some(PlaceInfo { name, kind, zone, location, country })
}
